/**
 * The customer's words, credited to the techs on the job (punch list #255, v2.6584). A customer's answer on `/rate`
 * (`customer_ratings`) used to stop at the office. Now every tech with a clock session on the job is credited with a
 * four or five star answer, and reads it the day it lands as a green strip on their home. Three stars or fewer stay
 * with the office (the card's call 1: five stars is the goal; a low answer is the lead's to talk through in person).
 *
 * Pure: who is credited, the office's line naming them, the parse of `my_customer_words()` and the strip's words.
 */
import { APP_CALENDAR_TZ, calendarYmdInAppTzFromIso, todayYmdInAppTz } from '../../utils/dateUtils.ts'

/** The lowest score a tech is credited with. Below it the answer is the office's (Needs you). */
export const CREDIT_AT_OR_ABOVE = 4

/** The strip reads back this many days; the week's card reads its own week out of the same list. */
export const CREDIT_WINDOW_DAYS = 56

// ---------- who is credited ----------

export type CreditSession = { user_id: string; job_ledger_id: string | null; travel_started_at: string | null; clocked_in_at: string; revoked_at?: string | null; rejected_at?: string | null }

/**
 * The techs credited on each job: every user with a session on it that was not revoked or rejected, the one who
 * pressed On my way first, then by first clock-in. Names come from `nameOf`; a user with no name is skipped.
 */
export function creditedTechsByJob(sessions: readonly CreditSession[], nameOf: (userId: string) => string | null | undefined): Map<string, string[]> {
  const byJob = new Map<string, Map<string, { travel: boolean; firstIn: string }>>()
  for (const s of sessions) {
    if (!s.job_ledger_id || s.revoked_at || s.rejected_at) continue
    const users = byJob.get(s.job_ledger_id) ?? byJob.set(s.job_ledger_id, new Map()).get(s.job_ledger_id)!
    const cur = users.get(s.user_id)
    const travel = Boolean(s.travel_started_at)
    if (!cur) users.set(s.user_id, { travel, firstIn: s.clocked_in_at })
    else users.set(s.user_id, { travel: cur.travel || travel, firstIn: cur.firstIn < s.clocked_in_at ? cur.firstIn : s.clocked_in_at })
  }
  const out = new Map<string, string[]>()
  for (const [jobId, users] of byJob) {
    const names = [...users.entries()]
      .sort((a, b) => (a[1].travel === b[1].travel ? a[1].firstIn.localeCompare(b[1].firstIn) : a[1].travel ? -1 : 1))
      .map(([userId]) => (nameOf(userId) ?? '').trim())
      .filter(Boolean)
    out.set(jobId, names)
  }
  return out
}

/** "Luis Ortega was on the job", "Luis Ortega and Jordan Price were on the job", "" for nobody. */
export function techsLine(names: readonly string[]): string {
  const n = names.filter((x) => x.trim())
  if (n.length === 0) return ''
  if (n.length === 1) return `${n[0]} was on the job`
  if (n.length === 2) return `${n[0]} and ${n[1]} were on the job`
  return `${n.slice(0, -1).join(', ')} and ${n[n.length - 1]} were on the job`
}

// ---------- the tech's read ----------

export type MyCustomerWord = {
  id: string
  customerName: string
  score: number
  words: string
  answeredAt: string
  googlePressedAt: string | null
  jobId: string
  jobNumber: string
  jobName: string
  jobAddress: string
  seenAt: string | null
}

const str = (v: unknown): string => (typeof v === 'string' ? v : v == null ? '' : String(v))
const strOrNull = (v: unknown): string | null => (typeof v === 'string' && v ? v : null)

/** `my_customer_words()`'s jsonb, typed. Anything that is not a list reads as none. */
export function parseMyCustomerWords(raw: unknown): MyCustomerWord[] {
  if (!Array.isArray(raw)) return []
  const out: MyCustomerWord[] = []
  for (const x of raw) {
    if (!x || typeof x !== 'object') continue
    const o = x as Record<string, unknown>
    const score = Number(o.score)
    if (!str(o.id) || !Number.isFinite(score) || score < CREDIT_AT_OR_ABOVE) continue
    out.push({
      id: str(o.id),
      customerName: str(o.customer_name),
      score,
      words: str(o.words).trim(),
      answeredAt: str(o.answered_at),
      googlePressedAt: strOrNull(o.google_pressed_at),
      jobId: str(o.job_id),
      jobNumber: str(o.job_number),
      jobName: str(o.job_name),
      jobAddress: str(o.job_address),
      seenAt: strOrNull(o.seen_at),
    })
  }
  return out.sort((a, b) => b.answeredAt.localeCompare(a.answeredAt))
}

/** The ones the tech has not pressed Got it on, newest first. */
export const unseenWords = (list: readonly MyCustomerWord[]): MyCustomerWord[] => list.filter((w) => !w.seenAt)

/** The answers that landed inside a week of the company calendar (inclusive), newest first. */
export function wordsInWeek(list: readonly MyCustomerWord[], week: { start: string; end: string }): MyCustomerWord[] {
  return list.filter((w) => {
    const ymd = calendarYmdInAppTzFromIso(w.answeredAt)
    return ymd >= week.start && ymd <= week.end
  })
}

// ---------- the strip's words ----------

export const customerFirstName = (name: string): string => name.trim().split(/\s+/)[0] || 'A customer'

const STARS_WORD: Record<number, string> = { 4: 'four stars', 5: 'five stars' }

/** "today", "yesterday", a weekday inside the week, else the day: the day the answer landed, on the company calendar. */
export function dayWord(iso: string, now: Date = new Date()): string {
  const ms = Date.parse(iso)
  if (Number.isNaN(ms)) return ''
  const ymd = calendarYmdInAppTzFromIso(iso)
  const today = todayYmdInAppTz(now)
  if (ymd === today) return 'today'
  const days = Math.round((Date.parse(`${today}T12:00:00Z`) - Date.parse(`${ymd}T12:00:00Z`)) / 86_400_000)
  if (days === 1) return 'yesterday'
  if (days > 1 && days < 7) return new Date(ms).toLocaleDateString('en-US', { weekday: 'long', timeZone: APP_CALENDAR_TZ })
  return new Date(ms).toLocaleDateString('en-US', { month: 'short', day: 'numeric', timeZone: APP_CALENDAR_TZ })
}

export type CustomerWordsStrip = {
  /** "Dana gave you five stars" */
  title: string
  /** Their words, or '' when they wrote none. */
  quote: string
  /** "Water heater at 1208 Mesquite Ln · Thursday" */
  place: string
  button: string
}

/** The green strip on the tech's home: the customer's first name, the stars, the words, the job and the day. */
export function stripWords(w: MyCustomerWord, now: Date = new Date()): CustomerWordsStrip {
  const stars = STARS_WORD[w.score] ?? `${w.score} stars`
  const job = w.jobName.trim() || (w.jobNumber ? `Job ${w.jobNumber}` : 'The job')
  const where = w.jobAddress.trim()
  const day = dayWord(w.answeredAt, now)
  const place = [where ? `${job} at ${where}` : job, day].filter(Boolean).join(' · ')
  return { title: `${customerFirstName(w.customerName)} gave you ${stars}`, quote: w.words, place, button: 'Got it' }
}
